import unittest

from solucao import pegar_letra


class TestOTextoTemPosicaoTambem(unittest.TestCase):
    def test_pega_a_primeira_letra(self):
        """pegar_letra devolve a letra da posicao 0"""
        self.assertEqual(pegar_letra("banana", 0), "b")

    def test_pega_a_segunda_letra(self):
        """pegar_letra devolve a letra da posicao 1"""
        self.assertEqual(pegar_letra("banana", 1), "a")

    def test_pega_a_ultima_letra(self):
        """pegar_letra devolve a letra da ultima posicao"""
        self.assertEqual(pegar_letra("banana", 5), "a")

    def test_pega_em_palavra_curta(self):
        """pegar_letra devolve a letra da ultima posicao de uma palavra curta"""
        self.assertEqual(pegar_letra("ola", 2), "a")
